(function(root){function cross(a,b,symbol='P'){const upper=symbol.toUpperCase(),lower=symbol.toLowerCase();const cells=[...a].flatMap(x=>[...b].map(y=>[x,y].sort((m,n)=>(m===upper?0:1)-(n===upper?0:1)).join('')));const genotypes={[upper+upper]:0,[upper+lower]:0,[lower+lower]:0};cells.forEach(x=>genotypes[x]+=25);return {cells,genotypes,dominant:100-genotypes[lower+lower],recessive:genotypes[lower+lower]}}root.GeneEngine={cross};if(typeof module!=='undefined')module.exports={cross};})(globalThis);
